class FourCal:
    def __init__(self, first: float, second: float):
        self.first = first
        self.second = second

    def add(self) -> float:
        return self.first + self.second

    def sub(self) -> float:
        return self.first - self.second

    def mul(self) -> float:
        return self.first * self.second

    def div(self) -> float:
        return self.first / self.second

calculator = FourCal(10, 2)
print(calculator.add())

class MoreFourCal(FourCal):
    def power(self) -> float:
        return self.first ** self.second

    def div(self) -> float:
        if self.second == 0:
            raise ZeroDivisionError("두 번째 값은 0이 될 수 없습니다.")
        return self.first / self.second

def main() -> None:
    print("이 파일을 직접 실행했습니다.")

if __name__ == "__main__":
    main()
